public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) return false; // If the array length is odd, it's impossible to pair up all elements

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = (num % k + k) % k; // Handle negative numbers correctly
        remainderCount[remainder]++;
    }

    // Check if numbers with remainder 0 can be paired
    if (remainderCount[0] % 2 != 0) return false;

    // Check if numbers with remainder i can be paired with numbers with remainder k-i
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) return false;
    }

    return true;
}

